import * as THREE from 'three';

const $=s=>document.querySelector(s), scene=new THREE.Scene();
scene.background=new THREE.Color(0x080d12);scene.fog=new THREE.FogExp2(0x101820,.012);
const camera=new THREE.PerspectiveCamera(73,innerWidth/innerHeight,.08,260);camera.rotation.order='YXZ';
const renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.65));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.02;document.body.prepend(renderer.domElement);
const clock=new THREE.Clock(), ray=new THREE.Raycaster(), tmp=new THREE.Vector3();
const mat=(color,rough=.85,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const M={ground:mat(0x202723),road:mat(0x1b2022),wall:mat(0x4c5049),wood:mat(0x453e35),wood2:mat(0x292a26),metal:mat(0x41494b,.42,.5),glass:new THREE.MeshStandardMaterial({color:0x263839,roughness:.2,metalness:.18,transparent:true,opacity:.48}),warm:new THREE.MeshStandardMaterial({color:0xffd49a,emissive:0xff9b43,emissiveIntensity:2}),cold:new THREE.MeshStandardMaterial({color:0x9caeaa,emissive:0x7d928e,emissiveIntensity:.42}),red:new THREE.MeshStandardMaterial({color:0x832f36,emissive:0x420910,emissiveIntensity:.4}),grass:mat(0x26342b),asphalt:mat(0x2a2d2c)};
scene.add(new THREE.HemisphereLight(0x8997a5,0x151b18,1.35));const moon=new THREE.DirectionalLight(0x96a6b1,1.5);moon.position.set(-30,60,-45);moon.castShadow=true;moon.shadow.mapSize.set(1024,1024);scene.add(moon);
const flashlight=new THREE.SpotLight(0xe4f0dc,0,23,Math.PI/7,.4,1.4);flashlight.position.set(0,0,0);flashlight.castShadow=false;camera.add(flashlight);flashlight.target.position.set(0,-.2,-1);camera.add(flashlight.target);scene.add(camera);
let started=false,paused=false,locked=false,hasFocus=false, yaw=0,pitch=0, flashOn=true, hiding=false,driving=false, highContrast=false;
const player={pos:new THREE.Vector3(0,1.65,3.2),health:100,stamina:100,flash:100,speed:5.2};
let flags={key:false,power:false,out:false,alex:false,sam:false,mike:false,engine:false,battery:false,tyres:0,tank:false,carkey:false,plugs:false,radiator:false,wiring:false,carStarted:false,escaped:false};
let bag=[], items=[], colliders=[], interactive=[], ghosts=[], companions=[], rain=null, car=null, exitBeacon=null;let toastTimer=0, saveTime=0, gameTime=0, driveSpeed=0;
const locationNames=[['HOME',0,3],['MARKET',-22,-18],['POLICE',22,-34],['GARAGE',-19,-50],['HOSPITAL',21,-60],['FUEL',-20,-79],['FACTORY',20,-91],['CAR',0,-70],['BRIDGE',0,-138]];
const worldFloor=new THREE.Mesh(new THREE.PlaneGeometry(500,500),M.ground);worldFloor.rotation.x=-Math.PI/2;worldFloor.position.y=-.09;worldFloor.receiveShadow=true;scene.add(worldFloor);
function box(parent,x,y,z,w,h,d,material,collide=true){const o=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;parent.add(o);if(collide)colliders.push({x,z,hw:w/2,hd:d/2});return o;}
function sphere(parent,x,y,z,r,material){const o=new THREE.Mesh(new THREE.SphereGeometry(r,12,10),material);o.position.set(x,y,z);o.castShadow=true;parent.add(o);return o;}
function addLamp(x,y,z,color=0xffd49a,power=5,dist=13){const l=new THREE.PointLight(color,power,dist,2);l.position.set(x,y,z);scene.add(l);return l;}
function wallSegment(x,y,z,w,h,d,material=M.wall){return box(scene,x,y,z,w,h,d,material,true)}
function buildRoad(){box(scene,0,-.02,-65,11,.12,180,M.road,false);for(let z=-5;z>-150;z-=10){const stripe=box(scene,0,.045,z, .13,.025,4,mat(0x777a70),false)}for(let side of [-1,1]){for(let z=-2;z>-148;z-=6){const post=box(scene,side*6.8,.5,z,.1,1,.1,M.wood2,false);sphere(scene,side*6.8,1.06,z,.13,M.cold)}}}
buildRoad();
// House shell, with a walkable back exit and a locked front entrance.
box(scene,0,-.08,3,14,.18,14,mat(0x342f2a),true);
wallSegment(-7,1.7,3,.35,3.4,14);wallSegment(7,1.7,3,.35,3.4,14);wallSegment(0,1.7,10,14,3.4,.35);wallSegment(-4.75,1.7,-4,4.5,3.4,.35);wallSegment(4.75,1.7,-4,4.5,3.4,.35);
// front and back door leaves
const frontDoor=box(scene,0,1.35,9.78,1.7,2.7,.16,M.wood2,false);const backDoor=box(scene,0,1.35,-3.78,1.6,2.7,.16,M.wood,false);
box(scene,-3.8,1.68,1,6.4,.15,.25,M.wood2,true);box(scene,2.3,.5,4.2,2.6,.9,1.4,M.wood,true);box(scene,-4.8,.35,-1,2.4,.7,1.3,M.wood,true);box(scene,-2.9,1.35,-1.7,.6,2.7,.17,M.wood2,true);
// Furniture and the unstable-house lighting.
box(scene,2.3,.34,4.2,2.55,.14,1.38,mat(0x555047),false);box(scene,2.3,.83,4.2,2.1,.75,.9,M.wood,false);box(scene,-4.8,.82,-1,2.3,.22,1.2,M.wood,false);
const houseLamp=addLamp(0,2.9,2,0xffcb8b,1.2,12);addLamp(2.2,1.8,4.2,0xffc984,.9,7);
// Broken upstairs doorway / dark stair suggestion.
for(let i=0;i<7;i++){box(scene,-5.7+i*.22,.2+i*.26,3.7-i*.43,1.6,.12,.65,M.wood2,true)}
function building(name,x,z,w,d,height=7,color=0x343b3b,kind='generic'){
 const group=new THREE.Group();group.position.set(x,0,z);scene.add(group);const body=mat(color), roof=mat(0x202729),trim=mat(0x151b1c);
 box(group,0,height/2,0,w,height,d,body,true);box(group,0,height+.18,0,w+.5,.4,d+.45,roof,true);
 // decorative facade and windows with weak interior glow
 for(const side of [-1,1]){for(let yy=2.2;yy<height-1;yy+=2.5){for(let xx=-w*.32;xx<=w*.32;xx+=w*.62){box(group,xx,yy,side*(d/2+.03),w*.22,1.05,.08,M.glass,false);box(group,xx,yy,side*(d/2+.08),.06,1.2,.06,trim,false);}}}
 box(group,0,1.35,d/2+.08,1.65,2.7,.15,M.wood2,false);box(group,0,.1,d/2+.25,2.5,.18,1.3,M.asphalt,false);
 const sign=new THREE.Mesh(new THREE.BoxGeometry(Math.min(w*.8,7),.38,.13),mat(0x202928));sign.position.set(0,height-1.1,d/2+.15);group.add(sign);
 // sign label via canvas texture
 const cv=document.createElement('canvas');cv.width=512;cv.height=96;const ctx=cv.getContext('2d');ctx.fillStyle='#192220';ctx.fillRect(0,0,512,96);ctx.fillStyle='#d2dcce';ctx.font='700 36px monospace';ctx.textAlign='center';ctx.fillText(name.toUpperCase(),256,61);const tx=new THREE.CanvasTexture(cv);const label=new THREE.Mesh(new THREE.PlaneGeometry(Math.min(w*.8,7),.38),new THREE.MeshBasicMaterial({map:tx,transparent:true}));label.position.set(0,height-1.1,d/2+.23);group.add(label);
 if(kind==='market'){box(group,-w*.22,1,-.2,1,.2,3,M.wood2,true);box(group,w*.22,1,-.2,1,.2,3,M.wood2,true)}
 if(kind==='garage'){box(group,0,2.8,-d/2-.15,w*.7,5,.2,M.metal,false);}
 addLamp(x,5,z+(d/2+.3),0xffbd83,1.6,16);return group;
}
building('Grocery',-22,-18,13,12,7,0x3e4440,'market');building('Police',22,-34,13,12,8,0x343d43);building('Auto repair',-19,-50,15,14,7,0x41423c,'garage');building('County hospital',21,-60,14,15,9,0x464646);building('Fuel stop',-20,-79,12,12,6,0x393e3d);building('Foundry',20,-91,17,17,10,0x353a38);
// Town trees, power poles, wreckage and a dim forest around the bridge.
const trunk=mat(0x332f29),leaf=mat(0x202c26);
for(let i=0;i<58;i++){let z=-12-Math.random()*130,side=(Math.random()<.5?-1:1)*(18+Math.random()*40);let h=4+Math.random()*7;const t=box(scene,side,h*.42,z,.42,h*.84,.42,trunk,false);const crown=new THREE.Mesh(new THREE.ConeGeometry(2+Math.random()*1.7,h*.75,7),leaf);crown.position.set(side,h*.95,z);crown.castShadow=true;scene.add(crown)}
for(let z=-8;z>-145;z-=20){box(scene,9,4,z,.22,8,.22,M.wood,false);box(scene,9,7.8,z,4,.15,.15,M.metal,false);for(let s of [-1,1]){const cable=new THREE.Mesh(new THREE.CylinderGeometry(.025,.025,20,5),M.metal);cable.position.set(9+s*1.4,7.6,z-10);cable.rotation.x=Math.PI/2;scene.add(cable)}}
// The bridge crossing is the end-of-road objective.
box(scene,0,-.05,-135,15,.3,14,mat(0x3c4544),false);for(let s of [-1,1]){box(scene,s*7,1,-135,.38,2,15,M.metal,false);for(let z=-129;z>=-141;z-=4)box(scene,s*7,3,z,.18,4,.18,M.metal,false)}
for(let i=0;i<16;i++){const rainDrop=new THREE.Mesh(new THREE.BoxGeometry(.012,.35,.012),new THREE.MeshBasicMaterial({color:0x9eb7c0,transparent:true,opacity:.28}));rainDrop.position.set((Math.random()-.5)*100,Math.random()*30,(Math.random()-.5)*180-50);scene.add(rainDrop);(rain??=[]).push(rainDrop)}

const partSpec=[
 {id:'battery',label:'Car battery',site:'Grocery',x:-22,z:-18,color:0x9b483a,shape:'box'},
 {id:'plugs',label:'Spark plugs',site:'Police station',x:22,z:-34,color:0x9fb3bb,shape:'sphere'},
 {id:'engine',label:'Engine block',site:'Auto repair',x:-19,z:-50,color:0x68706b,shape:'box'},
 {id:'tyre1',label:'Tyre 1 of 4',site:'Auto repair',x:-19,z:-50,color:0x252a29,shape:'torus'},
 {id:'tyre2',label:'Tyre 2 of 4',site:'Auto repair',x:-18,z:-50,color:0x252a29,shape:'torus'},
 {id:'tyre3',label:'Tyre 3 of 4',site:'Auto repair',x:-20,z:-51,color:0x252a29,shape:'torus'},
 {id:'tyre4',label:'Tyre 4 of 4',site:'Auto repair',x:-18,z:-51,color:0x252a29,shape:'torus'},
 {id:'tank',label:'Fuel tank',site:'Fuel stop',x:-20,z:-79,color:0x58646a,shape:'box'},
 {id:'carkey',label:'Ignition key',site:'Police station',x:22,z:-34,color:0xdfbd6c,shape:'key'},
 {id:'radiator',label:'Radiator',site:'County hospital',x:21,z:-60,color:0x65736e,shape:'box'},
 {id:'wiring',label:'Electrical wiring',site:'Foundry',x:20,z:-91,color:0x8c433c,shape:'coil'}
];
function makeItemMesh(spec){let m;if(spec.shape==='torus'){m=new THREE.Mesh(new THREE.TorusGeometry(.44,.16,8,16),mat(spec.color,.9));m.rotation.y=Math.PI/2}else if(spec.shape==='sphere'){m=new THREE.Mesh(new THREE.IcosahedronGeometry(.42,1),mat(spec.color,.35,.3))}else if(spec.shape==='key'){m=new THREE.Group();const ring=new THREE.Mesh(new THREE.TorusGeometry(.19,.045,7,12),mat(spec.color,.4,.7));ring.position.x=-.14;const shaft=box(m,.24,0,0,.54,.07,.07,mat(spec.color,.4,.7),false);m.add(ring)}else if(spec.shape==='coil'){m=new THREE.Mesh(new THREE.TorusKnotGeometry(.3,.07,32,6),mat(spec.color,.55,.3))}else{m=new THREE.Mesh(new THREE.BoxGeometry(.78,.5,.5),mat(spec.color,.55,.3))}if(spec.shape!=='key')m.castShadow=true;return m}
function addInteract(id,label,pos,action,mesh=null,kind='object'){
 const o={id,label,pos:new THREE.Vector3(...pos),action,mesh,kind,active:true};interactive.push(o);if(mesh){mesh.position.copy(o.pos);scene.add(mesh)}return o;
}
function sparkle(color=0xd5ed80){const g=new THREE.Mesh(new THREE.IcosahedronGeometry(.12,1),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.8}));const l=new THREE.PointLight(color,1.1,3);g.add(l);return g}
function makePickup(spec){const m=makeItemMesh(spec);m.position.set(spec.x,.52,spec.z);scene.add(m);const glow=sparkle(0xd5ed80);glow.position.set(spec.x,.95,spec.z);scene.add(glow);const o=addInteract(spec.id,`Take ${spec.label}`,[spec.x,.7,spec.z],()=>{if(bag.length>=8){notify('Your pack is full. Return to the car to unload.');return}if(flags[spec.id])return;bag.push(spec.id);flags[spec.id]=true;if(spec.id.startsWith('tyre'))flags.tyres++;scene.remove(m,glow);o.active=false;notify(`${spec.label} added to pack.`);updateHUD();checkpoint()},m,'pickup');o.mesh=m;}
for(const spec of partSpec)makePickup(spec);
// House key + fuse box. The key is easy to spot, the breaker is tucked behind furniture.
const houseKeySpec={label:'Back-door key',shape:'key',color:0xd9bd6f};const hk=makeItemMesh(houseKeySpec);hk.position.set(3.2,.88,2.4);hk.rotation.set(.3,.2,.3);scene.add(hk);addInteract('house-key','Take the back-door key',[3.2,1.03,2.4],()=>{if(flags.key)return;flags.key=true;bag.push('key');scene.remove(hk);notify('A brass key. The back door, maybe.');checkpoint()},hk,'pickup');
const breaker=box(scene,-5.7,1.38,1.1,.42,.8,.2,M.metal,false);box(scene,-5.7,1.38,.98,.3,.22,.07,M.red,false);addInteract('breaker','Reset the fuse box',[-5.7,1.4,1.25],()=>{if(!flags.key){notify('The fuse box is live. Find the back-door key first.');return}if(flags.power){notify('The breaker is already holding. For now.');return}flags.power=true;houseLamp.intensity=3.7;scene.fog.density=.01;notify('Power restored. Something moved upstairs.');checkHouseExit();checkpoint()},breaker);
addInteract('front-door','Try the front entrance',[0,1.3,9.7],()=>notify('Locked fast. The key will not turn from this side.'),frontDoor,'door');
function checkHouseExit(){if(flags.key&&flags.power){document.querySelector('#objectiveTitle').textContent='Leave through the back door';document.querySelector('#objectiveText').textContent='The rear lock should turn now. Do not look back.'}}
addInteract('back-door','Unlock the back door', [0,1.3,-3.9],()=>{if(!flags.key||!flags.power){notify('The lock needs a key, and the hall is still dark.');return}if(flags.out)return;flags.out=true;scene.remove(backDoor);notify('The door gives way. Rain and cold air rush in.');document.querySelector('#chapter').textContent='CHAPTER 02 · THE TOWN';document.querySelector('#objectiveTitle').textContent='Find your friends';document.querySelector('#objectiveText').textContent='Three signals remain. Find Alex, Sam and Mike. Then gather the car parts.';unlockTown();checkpoint()},backDoor,'door');
// Friend actors use simple, readable silhouettes; their rescue points also become companion spawn points.
const friendData=[{id:'sam',name:'Sam',x:-22,z:-18,color:0x99a98d,role:'Finds hidden things'}, {id:'alex',name:'Alex',x:-19,z:-50,color:0x9c7658,role:'Mechanic'}, {id:'mike',name:'Mike',x:20,z:-91,color:0x71879a,role:'Moves heavy objects'}];
function personMesh(color=0x9baba2){const g=new THREE.Group();const torso=new THREE.Mesh(new THREE.CapsuleGeometry(.29,.72,4,8),mat(color));torso.position.y=1.05;torso.castShadow=true;g.add(torso);const head=new THREE.Mesh(new THREE.SphereGeometry(.22,12,10),mat(0xb6b8ad));head.position.y=1.65;head.castShadow=true;g.add(head);const coat=new THREE.Mesh(new THREE.BoxGeometry(.52,.32,.24),mat(0x303a38));coat.position.set(0,1.13,.14);g.add(coat);return g}
for(const f of friendData){const model=personMesh(f.color);model.position.set(f.x,0,f.z);scene.add(model);model.visible=false;const c={...f,model,follow:false,active:true};companions.push(c);}
// Plan D: the sedan is an object built from visible, separately installable parts.
function makeCar(){const g=new THREE.Group();g.position.set(0,0,-70);scene.add(g);const shell=mat(0x343b38,.4,.45),dark=mat(0x11191a,.27,.25),rubber=mat(0x141718,.95),chrome=mat(0x77807d,.35,.75);box(g,0,1.05,0,2.55,.65,4.7,shell,false);box(g,0,1.72,-.25,2.15,.85,2.55,shell,false);box(g,0,1.78,-.22,1.9,.65,2.35,M.glass,false);box(g,0,1.42,2.15,2.15,.09,.16,chrome,false);box(g,0,1.12,-2.36,2.2,.18,.15,chrome,false);
 const wheels=[];for(const x of [-1.34,1.34])for(const z of [-1.48,1.55]){const wheel=new THREE.Mesh(new THREE.CylinderGeometry(.47,.47,.3,16),rubber);wheel.rotation.z=Math.PI/2;wheel.position.set(x,.48,z);wheel.castShadow=true;g.add(wheel);const hub=new THREE.Mesh(new THREE.CylinderGeometry(.21,.21,.32,12),chrome);hub.rotation.z=Math.PI/2;hub.position.copy(wheel.position);g.add(hub);wheels.push({wheel,hub})}
 const hood=box(g,0,1.51,1.18,2.25,.12,1.35,mat(0x252c2a,.4,.5),false);const trunk=box(g,0,1.48,-1.92,2.3,.14,.8,shell,false);const headlights=[];for(const x of [-.8,.8]){const l=new THREE.SpotLight(0xffe9ba,0,36,.38,.35,1.2);l.position.set(x,1.25,2.5);l.target.position.set(x,0,-5);g.add(l,l.target);headlights.push(l);const lamp=new THREE.Mesh(new THREE.BoxGeometry(.38,.2,.09),M.warm);lamp.position.set(x,1.32,2.37);g.add(lamp)}
 return {group:g,hood,wheels,headlights,installed:{}}}
car=makeCar();
const carInteractions=[['car-hood','Open the bonnet',[0,1.55,-68.8],()=>{if(!flags.out){notify('The car is beyond the town. Get out of the house first.');return}car.hood.rotation.x=car.hood.rotation.x>.2?0:-.42;car.hood.position.y=car.hood.rotation.x?1.72:1.51;notify('Bonnet '+(car.hood.rotation.x?'open. Bring the required parts.':'closed.'))}],
 ['car-interact','Inspect the abandoned sedan',[0,1.2,-67.5],()=>carAction()]];
for(const [id,label,pos,action]of carInteractions)addInteract(id,label,pos,action,null,'car');
function carAction(){if(!flags.out){notify('Too far from the house. Find the back exit first.');return}if(!car.hood.rotation.x){car.hood.rotation.x=-.42;car.hood.position.y=1.72;notify('Bonnet open. E again to fit a part.');return}const order=[['engine','Install engine'],['radiator','Install radiator'],['battery','Connect battery'],['wiring','Connect wiring'],['plugs','Fit spark plugs'],['tank','Fit fuel tank'],['tyres','Fit all four tyres']];for(const [id,verb]of order){const have=id==='tyres'?flags.tyres>=4:bag.includes(id);if(have&&!car.installed[id]){car.installed[id]=true;if(id!=='tyres')bag.splice(bag.indexOf(id),1);if(id==='tyres'){bag=bag.filter(v=>!v.startsWith('tyre'));for(const w of car.wheels){const g=new THREE.Mesh(new THREE.TorusGeometry(.47,.15,8,16),mat(0x242727));g.rotation.y=Math.PI/2;g.position.copy(w.wheel.position);car.group.add(g)} }if(id==='engine')box(car.group,0,1.14,-.2,1.1,.45,.9,mat(0x626963,.4,.6),false);if(id==='radiator')box(car.group,0,.92,1.6,1.3,.5,.12,M.metal,false);if(id==='battery')box(car.group,.72,1.06,-.4,.48,.35,.42,mat(0x744139),false);if(id==='wiring'){const wire=new THREE.Mesh(new THREE.TorusKnotGeometry(.32,.035,50,5),mat(0xa0433d,.6,.35));wire.position.set(-.7,1.15,-.4);car.group.add(wire)}notify(`${verb}. ${id==='tyres'?'All four wheels are ready.':'Part secured.'}`);updateHUD();checkpoint();return} }
 if(!flags.carkey&&bag.includes('carkey')){flags.carkey=true;bag.splice(bag.indexOf('carkey'),1);car.installed.key=true;notify('Ignition key placed on the dash.');updateHUD();return}
 const all=['engine','radiator','battery','wiring','plugs','tank','tyres'].every(k=>car.installed[k]);if(all&&flags.carkey){notify('All systems ready. Press E at the driver door to start.');return}notify('Still missing: '+order.filter(([id])=>!car.installed[id]).map(a=>a[0]==='tyres'?`tyres ${flags.tyres}/4`:a[0]).join(', ')+(flags.carkey?'':', ignition key'))}
addInteract('driver-door','Enter / start the car',[0,1,-72.6],()=>{if(!flags.out){notify('Get out of the house first.');return}if(!companions.every(c=>flags[c.id])){notify('The car needs all three friends. Find them before you leave.');return}const ready=['engine','radiator','battery','wiring','plugs','tank','tyres'].every(k=>car.installed[k])&&flags.carkey;if(!ready){notify('The engine will not turn over. Open the bonnet and finish the repairs.');return}if(!flags.carStarted){flags.carStarted=true;driving=true;car.group.position.copy(player.pos);car.group.position.y=0;driveSpeed=0;notify('Starter catches. Headlights cut through the rain. Drive to the bridge.');document.querySelector('#chapter').textContent='CHAPTER 03 · LAST RIDE';document.querySelector('#objectiveTitle').textContent='Reach the bridge';document.querySelector('#objectiveText').textContent='Keep moving. Stay on the road. Do not stop for the voices.';car.headlights.forEach(l=>l.intensity=18);return}driving=!driving;notify(driving?'Back in the driver seat.':'You step out into the rain.')},null,'car');

// Correct pickup points sit outside each building's front wall, so the town is genuinely walkable.
for(const s of partSpec){const place={battery:[-22,.6,-8],plugs:[22,.6,-26],engine:[-19,.6,-39],tyre1:[-16,.45,-40],tyre2:[-22,.45,-40],tyre3:[-16,.45,-43],tyre4:[-22,.45,-43],tank:[-20,.6,-70],carkey:[24,.6,-26],radiator:[21,.6,-50],wiring:[20,.6,-81]}[s.id];if(place){s.x=place[0];s.z=place[2]}}
// Move the corresponding physical pickups and action coordinates to the corrected town positions.
for(const o of interactive){const s=partSpec.find(p=>p.id===o.id);if(s){o.pos.set(s.x,.7,s.z);if(o.mesh)o.mesh.position.set(s.x,.52,s.z);const gl=o.mesh?.userData.glow;if(gl)gl.position.set(s.x,.95,s.z)}}
