// Parts are scavenged across town, then installed together at the sedan.
const partSpec=[
 {id:'engine',label:'Engine block',x:-19,z:-39,color:0x62635b},
 {id:'battery',label:'Car battery',x:-22,z:-8,color:0x85836c},
 {id:'tyres',label:'Four tyres',x:-16,z:-43,color:0x292b2a},
 {id:'tank',label:'Fuel tank',x:-20,z:-70,color:0x77705e},
 {id:'carkey',label:'Ignition key',x:24,z:-26,color:0xc2a75d},
 {id:'plugs',label:'Spark plugs',x:22,z:-26,color:0xb8b8a9},
 {id:'radiator',label:'Radiator',x:21,z:-50,color:0x647171},
 {id:'wiring',label:'Electrical wiring',x:20,z:-81,color:0x714449}
];
function pickupMesh(spec){const g=new THREE.Group(),core=box(g,0,0,0,spec.id==='tyres'?.75:.42,.24,spec.id==='tyres'?.75:.35,mat(spec.color,.58,.18),false);core.position.y=.1;const glow=new THREE.PointLight(0xc9dcaa,.5,2);glow.position.y=.5;g.add(glow);g.userData.glow=glow;return g}
for(const spec of partSpec){const mesh=pickupMesh(spec);addInteract(spec.id,`Take ${spec.label.toLowerCase()}`,[spec.x,.22,spec.z],()=>{if(bag.length>=8){notify('Your pack is full. Install parts at the sedan.');return}if(flags[spec.id])return;flags[spec.id]=true;bag.push(spec.id);scene.remove(mesh);if(spec.id==='tyres')flags.tyres=4;notify(`${spec.label} secured.`);updateHUD();checkpoint()},mesh,'pickup')}
const friendData=[{id:'sam',name:'Sam',role:'keeps calm under pressure',x:-21,z:-7,color:0x718b77},{id:'alex',name:'Alex',role:'knows engines',x:-18,z:-38,color:0x8992a2},{id:'mike',name:'Mike',role:'never leaves anyone behind',x:19,z:-80,color:0x9a776b}];
function friendMesh(color){const g=new THREE.Group();const body=new THREE.Mesh(new THREE.CylinderGeometry(.28,.36,1.05,9),mat(color));body.position.y=.86;g.add(body);const head=new THREE.Mesh(new THREE.SphereGeometry(.24,10,8),mat(0xb7a58d));head.position.y=1.58;g.add(head);const hood=new THREE.Mesh(new THREE.SphereGeometry(.27,10,6,0,Math.PI*2,0,Math.PI/2),mat(0x282e2d));hood.position.y=1.68;g.add(hood);return g}
for(const f of friendData){const model=friendMesh(f.color);model.position.set(f.x,0,f.z);model.visible=false;scene.add(model);companions.push({...f,model,follow:false})}
// Wrecked sedan and its serviceable components.
car={group:new THREE.Group(),installed:{},headlights:[]};car.group.position.set(0,0,-105);scene.add(car.group);
box(car.group,0,.72,0,2.1,.72,4.2,mat(0x343b3b,.55,.35),false);box(car.group,0,1.32,-.35,1.75,.72,2.15,M.glass,false);box(car.group,0,1.25,1.35,1.82,.12,.55,M.metal,false);box(car.group,-.72,.38,-1.7,.58,.58,.18,mat(0x202323),false);box(car.group,.72,.38,-1.7,.58,.58,.18,mat(0x202323),false);box(car.group,-.72,.38,1.7,.58,.58,.18,mat(0x202323),false);box(car.group,.72,.38,1.7,.58,.58,.18,mat(0x202323),false);
for(const x of [-.72,.72]){const lamp=new THREE.SpotLight(0xe4f0cf,0,38,Math.PI/7,.45,1.2);lamp.position.set(x,1,-2);lamp.target.position.set(x,0,-18);car.group.add(lamp,lamp.target);car.headlights.push(lamp)}
const installedBox=box(car.group,0,1.9,0,.3,.22,.3,M.warm,false);installedBox.visible=false;
addInteract('car','Inspect the abandoned sedan',[0,1,-101.5],()=>{if(!flags.out){notify('The road beyond the house is not safe yet.');return}if(!flags.alex||!flags.sam||!flags.mike){notify('We leave together. Find all three friends first.');return}const needed=['engine','battery','tyres','tank','carkey','plugs','radiator','wiring'];const missing=needed.filter(k=>!car.installed[k]&&!bag.includes(k));if(missing.length){notify(`Still needed: ${missing.map(k=>partSpec.find(p=>p.id===k).label).join(', ')}.`);return}for(const k of needed){car.installed[k]=true;flags[k]=true;bag=bag.filter(v=>v!==k)}flags.carStarted=true;car.headlights.forEach(l=>l.intensity=16);notify('The engine catches. Get in — keep to the road!');$('#objectiveTitle').textContent='Reach the bridge';$('#objectiveText').textContent='Drive north along the road. Do not stop for anything.';updateHUD();checkpoint()},null,'car');

