const keys=new Set();let focused=null,damageAt=0,win=false,journalOpen=false;
const hud=$('#hud'),titleScreen=$('#titleScreen'),pauseModal=$('#pauseModal'),journalModal=$('#journalModal'),prompt=$('#prompt');
function setPaused(value){paused=value;pauseModal.classList.toggle('open',value);if(value&&document.pointerLockElement)document.exitPointerLock();if(!value&&started)renderer.domElement.requestPointerLock?.();}
function beginGame(){if(started)return;started=true;titleScreen.style.display='none';hud.style.display='block';$('#mobileControls').style.display='flex';updateHUD();renderer.domElement.requestPointerLock?.();notify('Find the brass key. The back door is locked.');}
$('#startBtn').addEventListener('click',beginGame);
$('#controlsBtn').addEventListener('click',()=>{$('#modalTitle').textContent='Controls';$('#modalText').textContent='WASD move · Mouse look · Shift sprint · F flashlight · E interact · H hide · Tab journal · Esc pause. On touch screens, use the on-screen controls.';pauseModal.classList.add('open')});
$('#resumeBtn').addEventListener('click',()=>setPaused(false));
$('#saveBtn').addEventListener('click',()=>{checkpoint();notify('Checkpoint saved.');});
$('#quitBtn').addEventListener('click',()=>{paused=false;started=false;pauseModal.classList.remove('open');hud.style.display='none';titleScreen.style.display='grid';if(document.pointerLockElement)document.exitPointerLock()});
$('#settingsBtn').addEventListener('click',()=>{highContrast=!highContrast;document.body.style.filter=highContrast?'contrast(1.18) saturate(.8)':'';$('#settingsBtn').textContent=`SETTINGS: ${highContrast?'HIGH':'STANDARD'} CONTRAST`});
